# Who may accept a risk, by score: a "delegation of authority"
APPROVERS = [                 # (highest score this role may accept, role)
    (4, "team lead"),
    (9, "risk owner (a director)"),
    (16, "CISO and CTO together"),
    (25, "executive risk committee, reported to the board"),
]

def approver(likelihood, impact):
    score = likelihood * impact          # both on a 1 to 5 scale
    for limit, role in APPROVERS:
        if score <= limit:
            return score, role

for name, l, i in [("verbose logs in staging", 2, 2),
                   ("no MFA on the admin console", 4, 4),
                   ("unpatched internet-facing payment server", 5, 5)]:
    print(name, *approver(l, i), sep=" | ")

import datetime, yaml

APPETITE = 9                     # board: scores above 9 need a plan
TODAY = datetime.date(2026, 11, 13)

def band(score):
    return ("low" if score <= 4 else "medium" if score <= 9
            else "high" if score <= 16 else "critical")

for r in yaml.safe_load(open("risks.yaml")):
    score = r["likelihood"] * r["impact"]
    problems = []
    if not r.get("owner"):
        problems.append("no owner")
    if score > APPETITE and r["treatment"] == "accept":
        problems.append("accepted above appetite")
    until = r.get("accept_until")
    if r["treatment"] == "accept" and (until is None or until < TODAY):
        problems.append("acceptance expired")
    if r["treatment"] == "mitigate" and not r.get("controls"):
        problems.append("mitigate with no controls")
    print(f'{r["id"]} {score:>2} {band(score):<8} {r["treatment"]:<8}',
          "; ".join(problems) or "ok")

"""Weekly job (PCI DSS 6.4.3 / 11.6.1 idea): compare the scripts the payment
page actually serves with the approved inventory."""
import hashlib
from html.parser import HTMLParser

APPROVED = {   # src -> (business justification, sha256 of approved content)
    "/static/checkout.js": ("our checkout logic",
                            hashlib.sha256(b"// v42").hexdigest()),
    "https://js.payments.example/v3/": ("PSP card fields", None),  # vendor-managed
}

class Scripts(HTMLParser):
    def __init__(self):
        super().__init__(); self.found = []
    def handle_starttag(self, tag, attrs):
        if tag == "script":
            self.found.append(dict(attrs).get("src", "<inline>"))

def check(page_html, fetch):
    p = Scripts(); p.feed(page_html)
    for src in p.found:
        if src not in APPROVED:
            print("ALERT unapproved script:", src)
            continue
        why, expected = APPROVED[src]
        if expected and hashlib.sha256(fetch(src)).hexdigest() != expected:
            print("ALERT approved script changed:", src)
        else:
            print("ok", src, "-", why)

page = """<script src="/static/checkout.js"></script>
<script src="https://js.payments.example/v3/"></script>
<script src="https://cdn.stats-collector.example/a.js"></script>"""
check(page, fetch=lambda src: b"// v42")   # pretend download

