# Maximum fines are "whichever is higher" of a fixed amount and a share of
# worldwide annual turnover (undertakings). Regulators then decide the actual
# fine within the cap, considering the factors in GDPR Art. 83(2).
CAPS = {
    "GDPR Art. 83(4) (e.g. Arts 32-34)":   (10_000_000, 0.02),
    "GDPR Art. 83(5) (principles, rights)": (20_000_000, 0.04),
    "NIS2 essential entity (minimum cap)":  (10_000_000, 0.02),
    "NIS2 important entity (minimum cap)":  (7_000_000, 0.014),
    "CRA essential requirements, Art. 14":  (15_000_000, 0.025),
}

def cap(fixed, share, turnover):
    return max(fixed, share * turnover)

for turnover in (50e6, 5e9):
    print(f"turnover EUR {turnover:,.0f}")
    for name, (fixed, share) in CAPS.items():
        print(f"  {name:40} EUR {cap(fixed, share, turnover):>13,.0f}")

from datetime import datetime, timedelta

def add_business_days(start, n):
    day = start
    while n:
        day += timedelta(days=1)
        if day.weekday() < 5:          # Monday=0 .. Friday=4 (ignores holidays)
            n -= 1
    return day

aware = datetime(2026, 3, 2, 9, 0)        # Monday 09:00: breach confirmed
material = datetime(2026, 3, 11, 17, 0)   # Wednesday: board finds it material

clock = {
    "NIS2 early warning (24 h)":        aware + timedelta(hours=24),
    "GDPR Art. 33 authority (72 h)":    aware + timedelta(hours=72),
    "NIS2 incident notification (72 h)": aware + timedelta(hours=72),
    "SEC 8-K Item 1.05 (4 bus. days)":  add_business_days(material, 4),
    "Florida residents (30 days)":      aware + timedelta(days=30),
    "HIPAA individuals (60 days)":      aware + timedelta(days=60),
}
for what, due in sorted(clock.items(), key=lambda kv: kv[1]):
    print(f"{due:%a %d %b %H:%M}  {what}")
